import sys

def move(x, y, direction):
    if direction == 'U':
        return (x - 1, y)
    elif direction == 'R':
        return (x, y + 1)
    elif direction == 'D':
        return (x + 1, y)
    elif direction == 'L':
        return (x, y - 1)

