        positions = set()
        for i in range(K):
            x, y, direction_char = bacteria[i]
            X = int(bacteria[i][2])
            new_direction = (directions[direction_char] + X) % 4
            next_x, next_y = move(x, y, ['U', 'R', 'D', 'L'][new_direction])

            if next_x < 0 or next_x >= N or next_y < 0 or next_y >= M:
                new_direction = (new_direction + 2) % 4
                next_x, next_y = move(x, y, ['U', 'R', 'D', 'L'][new_direction])

            if (next_x, next_y) in positions:
                return _
            positions.add((next_x, next_y))

