from collections import deque

def simulate_bacteria(N, M, K, trap_row, trap_col, bacteria):
    directions = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
    opposite_directions = {'U': 'D', 'R': 'L', 'D': 'U', 'L': 'R'}

    def get_next_position(x, y, dx, dy):
        nx, ny = x + dx, y + dy
        if 0 <= nx < N and 0 <= ny < M:
            return nx, ny
        else:
            return x, y

    def turn_90_clockwise(direction, X):
        for _ in range(X):
            direction = opposite_directions[direction]
        return direction

    def turn_180_degrees(direction):
        return opposite_directions[opposite_directions[direction]]

    queue = deque()
    visited = set()

    for i in range(K):
        x, y, start_dir = bacteria[i][:3]
        X = int(bacteria[i][3])
        queue.append((x, y, start_dir, X))
        visited.add(((x, y), start_dir))

    time = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            x, y, dir, X = queue.popleft()
            if (x, y) == (trap_row - 1, trap_col - 1):
                return time

            new_dir = turn_90_clockwise(dir, X)
            nx, ny = get_next_position(x, y, *directions[new_dir])

            if (nx, ny) == (trap_row - 1, trap_col - 1):
                return time + 1

            if ((nx, ny), new_dir) not in visited:
                visited.add(((nx, ny), new_dir))
                queue.append((nx, ny, new_dir, X))

        time += 1

    return -1

